TLM.f("Tempora/Pasc5-3",{"officium":"Feria Quarta in Rogationibus, In Vigilia Ascensionis","rule":["Oratio Dominica","Gloria","no Credo","Suffr=Maria3"],"ruleInherited":["Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"fallback":"Tempora/Pasc5-0","sections":{"Introitus":[{"k":"ref","la":"Is 48:20"},{"k":"text","la":"Vocem jucunditátis annuntiáte, et audiátur, allelúja: annuntiáte usque ad extrémum terræ: liberávit Dóminus pópulum suum, allelúja, allelúja"},{"k":"ref","la":"Ps 65:1-2"},{"k":"text","la":"Jubiláte Deo, omnis terra, psalmum dícite nómini ejus: date glóriam laudi ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Vocem jucunditátis annuntiáte, et audiátur, allelúja: annuntiáte usque ad extrémum terræ: liberávit Dóminus pópulum suum, allelúja, allelúja"}],"Oratio":[{"k":"text","la":"Deus, a quo bona cuncta procédunt, largíre supplícibus tuis: ut cogitémus, te inspiránte, quæ recta sunt; et, te gubernánte, eadem faciámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios"},{"k":"ref","la":"Eph 4:7-13"},{"k":"text","la":"Fratres: Unicuíque nostrum data est grátia secúndum mensúram donatiónis Christi. Propter quod dicit: Ascéndens in altum, captívam duxit captivitátem: dedit dona homínibus. Quod autem ascéndit, quid est, nisi quia et descéndit primum in inferióres partes terræ? Qui descéndit, ipse est et qui ascéndit super omnes cœlos, ut impléret ómnia. Et ipse dedit quosdam quidem apóstolos, quosdam autem prophétas, álios vero evangelístas, álios autem pastóres et doctóres, ad consummatiónem sanctórum in opus ministérii, in ædificatiónem córporis Christi: donec occurrámus omnes in unitátem fídei, et agnitiónis Fílii Dei, in virum perféctum, in mensúram ætátis plenitúdinis Christi."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Surréxit Christus, et illúxit nobis, quos rédemit sánguine suo. Allelúja.","mark":"V"},{"k":"ref","la":"Joannes 16:28"},{"k":"text","la":"Exívi a Patre, et veni in mundum: íterum relínquo mundum, et vado ad Patrem. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joannes 17:1-11"},{"k":"text","la":"In illo témpore: Sublevátis Jesus óculis in cœlum, dixit: Pater, venit hora, clarífica Fílium tuum, ut Fílius tuus claríficet te: sicut dedísti ei potestátem omnis carnis, ut omne, quod dedísti ei, det eis vitam ætérnam. Hæc est autem vita ætérna: ut cognóscant te, solum Deum verum, et quem misísti Jesum Christum. Ego te clarificávi super terram: opus consummávi, quod dedísti mihi, ut fáciam: et nunc clarífica me tu, Pater, apud temetípsum, claritáte, quam hábui, priúsquam mundus esset, apud te. Manifestávi nomen tuum homínibus, quos dedísti mihi de mundo. Tui erant, et mihi eos dedísti; et sermónem tuum servavérunt. Nunc cognovérunt, quia ómnia, quæ dedísti mihi, abs te sunt: quia verba, quæ dedísti mihi, dedi eis: et ipsi accepérunt, et cognovérunt vere, quia a te exivi, et credidérunt, quia tu me misísti. Ego pro eis rogo, non pro mundo rogo, sed pro his, quos dedísti mihi: quia tui sunt: et mea ómnia tua sunt, et tua mea sunt: et clarificátus sum in eis. Et jam non sum in mundo, et hi in mundo sunt, et ego ad te vénio."}],"Offertorium":[{"k":"ref","la":"Ps 65:8-9; 65:20"},{"k":"text","la":"Benedícite, gentes, Dóminum, Deum nostrum, et obaudíte vocem laudis ejus: qui pósuit ánimam meam ad vitam, et non dedit commovéri pedes meos: benedíctus Dóminus, qui non amóvit deprecatiónem meam et misericórdiam suam a me, allelúja."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, fidélium preces cum oblatiónibus hostiárum: ut, per hæc piæ devotiónis offícia, ad cœléstem glóriam transeámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 95:2"},{"k":"text","la":"Cantáte Dómino, allelúja: cantáte Dómino et benedícite nomen ejus: bene nuntiáte de die in diem salutáre ejus, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Tríbue nobis, Dómine, cœléstis mensæ virtúte satiátis: et desideráre, quæ recta sunt, et desideráta percípere."},{"k":"macro","name":"Per Dominum"}]},"hr":{"220adaabf86db148":{"t":"Iz 48, 20, Ps 65, 1-2\n(Iz 48, 20) Navijestite radosnu riječ da se čuje, <i>aleluja</i>.\nNavijestite do kraja zemlje: Oslobodio je Bog svoj narod, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 65, 1-2) Kličite Bogu, sve zemlje, pjevajte pjesmu imenu njegovu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 48, 20) Navijestite radosnu riječ da se čuje, <i>aleluja</i>.\nNavijestite do kraja zemlje: Oslobodio je Bog svoj narod, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Izai, 48, 20). Radosnu riječ naviještajte, da se čuje, aleluja; naviještajte do na kraj zemlje: Oslobodi, Gospodine, puk svoj. Aleluja, aleluja. (Ps. 65, 1, 2) Pokiikni Bogu sva zemljo, pjevajte pjesmu imenu njegovu; dajte slavu hvali njegovoj. Slava Ocu . . . Radosnu riječ . . .","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"},"a2273fd2a27e344c":{"t":"<i>Pomolimo se</i>.\nBože, od koga proizlaze sva dobra, podaj nama koji ti se molimo da po tvojem nadahnuću mislimo što je pravo i pod tvojim vodstvom da to činimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, od kojega ishode sva dobra, podaj inoliteljima svojim, da po Tvojemu nadahnuću 6to je pravo mislimo, i ipo Tvojoj upravi i činimo, po G. n.","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"},"b813d9523ead8afe":{"t":"Ef 4, 7-13\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo! Svakom je od nas dana milosti po mjeri Kristova dara. Zato kaže Pismo: Uzašao je na visinu, za sobom je poveo plijen i ljudima je razdijelio darove. Ali što znači da je uzašao, nego da je najprije sišao u donje dijelove zemlje? Koji je sišao, onaj je isti koji je i uzašao nad sve nebo da ispuni sve. I on postavi da jedni budu apostoli, drugi proroci, jedni evanđelisti, drugi pastiri i učitelji; da se sveti usavrše za djelo službe, na sazidanje tijela Kristova, dok svi ne dođemo do jedinstva vjere i spoznaje Sina Božjega, do savršenoga čovjeka, do mjere dobe punine Kristove.","kn":"Čitanje poslanice bi. Pavla apostola Efežanima (4, 7-13). Braćo! Svakom je od nas dana milost. PO mjeri Kristova dara. Zato kaže Pismo; Uzašao je na visinu, sa sobom poveo plijen i ljudima razdijelio đarove.t Mj što znači, da je uzašao, nego da je najprije sišao u do-nje dijelove zemlje? Koji je sišao, -onaj je isti, koji je i uzašao nad sve nebo, da ispuni sve stvari. I on jedne postavi, da budu apostoli, drugi proroci, jedni evanđelisti, drugi pastiri i učitelji, da se sveti usavrše za djelo službe, na sazidanje tijela Kristova, dok svi ne dođemo do jedinstva vjere i spoznaje Sina Božjega, do savršenoga čovjeka, do mjere dobe punine Kristove. '","knRef":"Kniewald 1942, str. 748–749 (snimka 375) (OCR)"},"e28abe3e36b0e886":{"t":"Iv 16, 28\n<i>Aleluja</i>, <i>aleluja</i>.\nKrist je uskrsnuo i prosvijetlio nas koje je otkupio svojom krvlju, <i>aleluja</i>.\n(Iv 16, 28) Izišao sam od Oca i došao na svijet, sad opet ostavljam svijet i idem Ocu, <i>aleluja</i>.","kn":"Aleliija, aleluja. Uskrsnuo je Krist i zasja nama, koje otkupi krvlju svojom, aleluja. (Iv. 16, 28) Izišao sam od Oca 1 došao na svijet; opet ostavljam svijet i idem k Ocu, Aleluja.","knRef":"Kniewald 1942, str. 328–329 (snimka 165) (OCR)"},"6f5559a444cd8bd5":{"t":"Io 17, 1-11\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme podigne Isus oči prema nebu i reče: Oče, dođe čas, proslavi Sina svojega da i Sin tvoj proslavi tebe, kao što si mu dao vlast nad svakim tijelom, da svemu što si mu dao dade život vječni. A ovo je život vječni da upoznaju tebe jedinoga pravog Boga i koga si poslao Isusa Krista. Ja tebe proslavih na zemlji, dovrših djelo koje si mi dao da učinim. Sad proslavi ti mene, Oče, kod tebe istom slavom koju sam imao kod tebe prije nego je svijet postao. Objavio sam ime tvoje ljudima koje si mi dao od svijeta. Tvoji su bili i meni si ih dao. Tvoje su riječi opsluživali. Sad su upoznali da je od tebe sve što si mi dao, jer sam im dao riječi koje si mi dao. Oni su primili i zaista upoznali da sam izišao od tebe i vjerovali su da si me ti poslao. Za njih molim. Ne molim za svijet, nego za ove koje si mi dao, jer su tvoji. I sve što je moje tvoje je, a sve što je tvoje moje je. I proslavio sam se u njima. Više nisam na svijetu, nego oni ostaju na svijetu, a ja k tebi dolazim.","kn":"t Slijedi sv. evanđelje po Ivanu (17. 1-11). U ono vrijeme, podignuvši Isus oči na nebo reče, Oče; Dođe čas, proslavi Sina svojega, da i Sin Tvoj proslavi Tebe: Kao što si mu dao vlast nad svakim tijelom, da svemu, što si mu dao, dade život vječni. A ovo je život vječni: da poznaju Tebe, jedinoga, pravoga Boga i koga si poslao, Isusa Krista. Ja Tebe proslavili na zemlji: djelo sam dovršio, koje si mi dao' da učinim, i sad proslavi Ti mene. Oče, kod Tebe istom slavom, koju imadoh kod Tebe prije nego svijet postade. Ja objavih ime Tvoje ljudima, koje si mi dao od svijeta. Tvoji bijahu, pa si ih meni dao: i riječi Tvoje opslužiše. Sad upoznaše, da je sve, što Bi mi dao, od.Tebe; jer riječi, koje si dao meni, dadoh njima: i oni primiše i spoznaše, da je istinito, da od Tebe izađoh, i vjerovaše, da si me Ti poslaO'. Ja se za njih molim, ne molim se za svijet, nego za ove, koje si mi dao, jer su Tvoji: i moje je sve Tvoje, i Tvoje moje je: i proslavih se u njima, I više nijesam na svijetu, i ja idem k Tebi.","knRef":"Kniewald 1942, str. 332–333 (snimka 167) (OCR)"},"737e5c98a96e3404":{"t":"Ps 65, 8-9 i 20\nBlagoslivljajte, narodi, Gospodina našega Boga i navješćujte njegovu hvalu, jer on je dao život mojoj duši i nije dopustio, da mi se spotakne noga. Blagoslovljen Bog, koji nije odbio moje molitve, niti odvratio svoga milosrđa od mene, <i>aleluja</i>.","kn":"(Ps. 65, 8, 9, 20). Blagosivajte narodi Gospodina Boga našega i razglasujte slavu njegovu. On je duši mojoj darovao život 1 nije dao da mi se omaknu noge. Blagoslovljen Gospodin, koji nije odvratio moje molitve i svoga milosrđa od mene.","knRef":"Kniewald 1942, str. 184–185 (snimka 93) (OCR)"},"0fd2e8f96ba76c4c":{"t":"Sa žrtvenim prinosima primi, Gospodine, i molitve svojih vjernika da po ovoj službi pobožne odanosti prijeđemo u nebesku slavu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, molimo. Gospodine, molitve svoga puka, koji Ti prinosi ove žrtve, da po ovoj službi svete pobožnosti prijeđemo u nebesku slavu, po G. n.. *","knRef":"Kniewald 1942, str. 306–307 (snimka 154) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"aa68f0aee886ab03":{"t":"Ps 95, 2\nPjevajte Gospodinu, aleluja, pjevajte Gospodinu i blagoslivljajte njegovo ime. Naviještajte iz dana u dan njegovo spasenje, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 95, 2). Pjevajte Gosipodinu, aleluja; pjevajte Gospodinu i blagosiljajte ime njegovo, naviještajte iz dana u dan spasenje njegovo, aleluja, aleluja.","knRef":"Kniewald 1942, str. 328–329 (snimka 165) (OCR)"},"75d9734be7b054fc":{"t":"<i>Pomolimo se</i>.\nUdijeli, Gospodine, nama koji smo nasićeni snagom s nebeskog stola da težimo za onim što je pravo i da postignemo ono za čim težimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Udijeli, Gospodine, nama, koji smo nahranjeni krepošću nebeskoga stola, da žudimo što je pravo, i žuđeno da primimo, po G. .n.","knRef":"Kniewald 1942, str. 328–329 (snimka 165) (OCR)"}}});
